      const token = await wait.createToken();
      fs.writeFileSync("/home/user/resilient-pipeline/waitpoint_token.txt", token.id);

      const completion = await wait.forToken<{ correctedInput: string }>(token.id);

      if (!completion.ok) {
        throw new Error("Waitpoint failed");
      }

      const result = await unreliableTask.triggerAndWait({
        input: completion.output.correctedInput,
        shouldFail: false,
      });

      return result.unwrap();
    }
  },
});

